"use client";

import { notFound } from "next/navigation";
import { projects } from "@/components/Projects/constants";
import Link from "next/link";
import { ArrowLeft } from "lucide-react";
import { use } from "react";
import CornersMenu from "@/components/Menu/CornersMenu";

interface ProjectPageProps {
    params: Promise<{ slug: string }>;
}

export default function ProjectPage({ params }: ProjectPageProps) {
    const { slug } = use(params);
    const project = projects.find((p) => p.slug === slug);

    if (!project) {
        notFound();
    }

    return (
        <main>
            <CornersMenu />
            <div className="relative w-full h-screen overflow-hidden bg-black p-16">
                {/* Media Background */}
                <div className="absolute inset-20 z-0 rounded-2xl">
                    {project.mediaType === "video" ? (
                        <video
                            className="w-full h-full object-cover rounded-2xl"
                            src={project.mediaSrc}
                            autoPlay
                            muted
                            loop
                            playsInline
                        />
                    ) : (
                        // eslint-disable-next-line @next/next/no-img-element
                        <img
                            src={project.mediaSrc}
                            alt={project.title}
                            className="w-full h-full object-cover"
                        />
                    )}
                    {/* Dark Overlay */}
                    <div className="absolute inset-0 bg-black/50 z-10" />
                </div>

                {/* Back Button */}
                <Link
                    href="/"
                    className="absolute top-8 left-8 z-30 group flex items-center gap-2 text-white/70 hover:text-white transition-colors duration-300 font-inter text-sm tracking-widest uppercase"
                >
                    <div className="w-8 h-8 rounded-full border border-white/30 flex items-center justify-center group-hover:bg-white group-hover:text-black transition-colors duration-500">
                        <ArrowLeft size={14} />
                    </div>
                    VOLVER
                </Link>

                {/* Content */}
                <div className="relative z-20 w-full h-full flex flex-col justify-end p-6 md:px-12 md:py-8 gap-4">
                    <div>
                        <h1 className="text-white font-schabo text-[13vw] leading-[0.85] uppercase">
                            {project.title}
                        </h1>
                    </div>

                    <div className="w-full h-px bg-white/30" />

                    <div className="flex justify-start items-center gap-12 md:py-2">
                        <div className="flex flex-col">
                            <span className="text-sm font-bold tracking-widest text-white">DIRECCIÓN</span>
                            <span className="text-2xl font-inter font-light text-white/70">{project.director}</span>
                            <span className="text-white/50">EST. {project.year}</span>
                        </div>
                    </div>
                </div>
            </div>
        </main>
    );
}
